<script setup lang="ts">
import { IconBrandTelegram, IconCalendarTime, IconUsers, IconHistory, IconPlus, IconLogout, IconX, IconRefresh, IconSend, IconPencil, IconTrash, IconPlayerPause, IconPlayerPlay, IconSearch, IconArrowRight } from '@tabler/icons-vue'
import type { Account, Task, Chat, Run } from '../shared/types'
const ready=ref(false), authenticated=ref(false), scheduler=ref(false), busy=ref(false), error=ref(''), notice=ref(''), password=ref('')
const tab=ref('tasks'), accounts=ref<Account[]>([]), tasks=ref<Task[]>([]), runs=ref<Run[]>([])
const modal=ref<'task'|'login'|null>(null), editId=ref(''), chats=ref<Chat[]>([]), chatSearch=ref(''), hasMore=ref(false), loadingChats=ref(false)
const logAccount=ref(''),logTask=ref(''),logPage=ref(1),logTotal=ref(0)
const loginId=ref(''), qr=ref(''),loginStatus=ref('waiting'),tgPassword=ref(''),loginError=ref(''),qrExpiry=ref(0)
const form=reactive({name:'',account_id:'',chat_id:'',text:'',time:'09:00',timezone:'Asia/Shanghai',enabled:true})
const zones=['Asia/Shanghai','Asia/Hong_Kong','Asia/Tokyo','Asia/Singapore','UTC','Europe/London','Europe/Berlin','America/New_York','America/Los_Angeles']
const visibleChats=computed(()=>chats.value.filter(c=>`${c.title} ${c.username} ${c.id}`.toLowerCase().includes(chatSearch.value.toLowerCase())))
const labels:Record<string,string>={connected:'已连接',reauth_required:'需要重新登录',success:'发送成功',failed:'发送失败',unknown:'结果未知',skipped:'已跳过',pending:'等待执行',running:'发送中'}
const accountName=(id:string)=>accounts.value.find(a=>a.id===id)?.label||id
const format=(s:string|null)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—'
let previousFocus:HTMLElement|null=null
watch(modal,async value=>{
  if(value){previousFocus=document.activeElement as HTMLElement;await nextTick();document.querySelector<HTMLElement>('.modal button, .modal input')?.focus()}
  else previousFocus?.focus()
})
function trapFocus(event:KeyboardEvent){
  if(!modal.value||event.key!=='Tab')return
  const items=Array.from(document.querySelectorAll<HTMLElement>('.modal button:not(:disabled), .modal input:not(:disabled), .modal select:not(:disabled), .modal textarea:not(:disabled)')).filter(el=>el.getClientRects().length)
  const first=items[0],last=items[items.length-1]
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}
}
let polling:ReturnType<typeof setInterval>|undefined,refreshTimer:ReturnType<typeof setInterval>|undefined
async function api<T>(url:string,options:Record<string,unknown>={}):Promise<T>{
  try{return await $fetch<T>('/api/'+url,options)}catch(e:any){if(e.status===401){authenticated.value=false}throw new Error(e.data?.message||e.data?.statusMessage||e.message||'请求失败')}
}
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function refresh(){[accounts.value,tasks.value]=await Promise.all([api<Account[]>('accounts'),api<Task[]>('tasks')]);if(tab.value==='runs')await loadRuns()}
async function loadRuns(){const q=new URLSearchParams({page:String(logPage.value),account:logAccount.value,task:logTask.value});const r=await api<{items:Run[];total:number}>('runs?'+q);runs.value=r.items;logTotal.value=r.total}
async function switchTab(value:string){tab.value=value;await action(refresh)}
async function signIn(){await action(async()=>{await api('auth/login',{method:'POST',body:{password:password.value}});password.value='';await initialize()})}
async function initialize(){const s=await api<{scheduler:boolean}>('auth/session');authenticated.value=true;scheduler.value=s.scheduler;await refresh()}
async function signOut(){await action(async()=>{await closeModal();await api('auth/logout',{method:'POST'});authenticated.value=false})}
async function openTask(task?:Task){editId.value=task?.id||'';Object.assign(form,task?{...task,enabled:Boolean(task.enabled)}:{name:'',account_id:accounts.value[0]?.id||'',chat_id:'',text:'',time:'09:00',timezone:'Asia/Shanghai',enabled:true});chats.value=[];chatSearch.value='';modal.value='task';if(form.account_id)await action(()=>loadChats(false,false))}
async function loadChats(refresh=false,more=false){
  loadingChats.value=true
  const account=form.account_id
  try{const r=await api<{items:Chat[];hasMore:boolean}>(`accounts/${account}/chats?refresh=${refresh}&more=${more}`);if(form.account_id===account){chats.value=r.items;hasMore.value=r.hasMore}}finally{loadingChats.value=false}
}
async function changeAccount(){form.chat_id='';chats.value=[];if(form.account_id)await action(()=>loadChats())}
async function saveTask(){await action(async()=>{await api('tasks'+(editId.value?'/'+editId.value:''),{method:editId.value?'PUT':'POST',body:{...form}});await closeModal();await refresh();notice.value='任务已保存'})}
async function toggle(task:Task){await action(async()=>{await api('tasks/'+task.id,{method:'PUT',body:{...task,enabled:!task.enabled}});await refresh()})}
async function deleteTask(task:Task){if(!confirm(`删除任务「${task.name}」？执行记录会保留。`))return;await action(async()=>{await api('tasks/'+task.id,{method:'DELETE'});await refresh()})}
async function testTask(task:Task){if(!confirm(`现在以「${accountName(task.account_id)}」向「${task.chat_title}」发送以下文字？\n\n${task.text}`))return;await action(async()=>{const r=await api<Run>('tasks/'+task.id+'/test',{method:'POST',body:{requestId:crypto.randomUUID()}});notice.value=(labels[r.status]||r.status)+(r.error?'：'+r.error:'');await refresh()})}
async function deleteAccount(a:Account){if(!confirm(`退出账号「${a.label}」并删除其所有任务？历史记录会保留。`))return;await action(async()=>{await api('accounts/'+a.id,{method:'DELETE'});await refresh()})}
async function openLogin(){await action(async()=>{const r=await api<{id:string}>('logins',{method:'POST'});loginId.value=r.id;qr.value='';loginStatus.value='waiting';loginError.value='';modal.value='login';polling=setInterval(()=>void pollLogin(),2000);await pollLogin()})}
let pollActive=false
async function pollLogin(){if(pollActive||!loginId.value)return;pollActive=true;const id=loginId.value;try{const r=await api<any>('logins/'+id);if(loginId.value!==id)return;loginStatus.value=r.state;qr.value=r.qr||'';qrExpiry.value=r.expires||0;loginError.value=r.error||'';if(r.state==='success'){await closeModal();await refresh();notice.value='Telegram 账号已连接'}}catch(e:any){loginError.value=e.message;clearInterval(polling)}finally{pollActive=false}}
async function sendPassword(){await action(async()=>{await api('logins/'+loginId.value+'/password',{method:'POST',body:{password:tgPassword.value}});tgPassword.value='';await pollLogin()})}
async function closeModal(){if(polling)clearInterval(polling);if(loginId.value){const id=loginId.value;loginId.value='';await api('logins/'+id,{method:'DELETE'}).catch(()=>{})}modal.value=null;tgPassword.value=''}
onMounted(async()=>{document.addEventListener('keydown',trapFocus);try{await initialize()}catch{}finally{ready.value=true}refreshTimer=setInterval(()=>{if(authenticated.value&&!modal.value)void refresh().catch(()=>{})},15000)})
onBeforeUnmount(()=>{document.removeEventListener('keydown',trapFocus);clearInterval(polling);clearInterval(refreshTimer)})
</script>

<template>
  <div v-if="!ready" class="loading-screen">正在载入管理台…</div>
  <div v-else-if="!authenticated" class="login-page">
    <section class="login-intro"><div class="brand"><IconBrandTelegram :size="30"/> Telegram Daily</div><div><span class="eyebrow">每天的消息，按时抵达</span><h1>把重复的事，<br>交给时间。</h1><p>连接你的 Telegram 账号，为固定消息安排一个时间。任务会在后台运行，你可以安心关掉网页。</p></div><small>个人 Telegram 定时发送管理台</small></section>
    <main class="login-form"><form @submit.prevent="signIn"><span class="eyebrow">管理入口</span><h2>欢迎回来</h2><p class="muted">输入管理员密码，管理账号与每日任务。</p><label>管理员密码<input v-model="password" type="password" autocomplete="current-password" required maxlength="1024" placeholder="请输入密码"></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'正在登录…':'登录管理台'}} <IconArrowRight :size="18"/></button><small class="muted">管理员密码由部署环境配置。</small></form></main>
  </div>
  <div v-else class="shell">
    <aside class="sidebar"><a class="brand" href="#" @click.prevent="switchTab('tasks')"><IconBrandTelegram :size="28"/> <span>Telegram<small>DAILY</small></span></a><div class="nav-label">工作空间</div><nav><button :class="{active:tab==='tasks'}" @click="switchTab('tasks')"><IconCalendarTime :size="20"/>每日任务<span>{{tasks.length}}</span></button><button :class="{active:tab==='accounts'}" @click="switchTab('accounts')"><IconUsers :size="20"/>Telegram 账号<span>{{accounts.length}}</span></button><button :class="{active:tab==='runs'}" @click="switchTab('runs')"><IconHistory :size="20"/>执行记录</button></nav><div class="sidebar-bottom"><span class="status-dot" :class="{off:!scheduler}"></span>{{scheduler?'后台调度已开启':'后台调度已关闭'}}<button class="logout" @click="signOut"><IconLogout :size="18"/>退出登录</button></div></aside>
    <main class="workspace"><header class="topbar"><span>个人工作空间 <span class="slash">/</span> {{tab==='tasks'?'每日任务':tab==='accounts'?'Telegram 账号':'执行记录'}}</span><span class="admin-label">管理员</span></header>
      <div class="content"><div v-if="!scheduler" class="banner">后台调度当前关闭。部署时设置 SCHEDULER_ENABLED=true 并开启 InstaCloud Always On，任务才会自动发送。</div><div v-if="error" role="alert" class="error toast">{{error}}<button aria-label="关闭错误" @click="error=''">×</button></div><div v-if="notice" role="status" class="notice toast">{{notice}}<button aria-label="关闭提示" @click="notice=''">×</button></div>
        <div class="page-heading"><div><span class="eyebrow">{{tab==='tasks'?'SCHEDULE':tab==='accounts'?'CONNECTIONS':'ACTIVITY'}}</span><h1>{{tab==='tasks'?'每日任务':tab==='accounts'?'Telegram 账号':'执行记录'}}</h1><p class="muted">{{tab==='tasks'?'一段固定文字，一个指定时间。其余的交给后台。':tab==='accounts'?'通过手机 Telegram 扫码，连接你要使用的账号。':'查看每一次发送的结果，及时发现需要处理的问题。'}}</p></div><button v-if="tab==='tasks'" class="primary" :disabled="busy||!accounts.length" @click="openTask()"><IconPlus :size="18"/>新建任务</button><button v-else-if="tab==='accounts'" class="primary" :disabled="busy" @click="openLogin"><IconPlus :size="18"/>连接账号</button><button v-else :disabled="busy" @click="action(loadRuns)"><IconRefresh :size="18"/>刷新记录</button></div>
        <template v-if="tab==='tasks'">
          <div class="summary"><div><strong>{{tasks.filter(t=>t.enabled).length}}</strong><span>运行中的任务</span></div><div><strong>{{accounts.length}}</strong><span>已添加账号</span></div><p>按照任务时区每日执行<br><span class="muted">错过时间自动跳过，不补发</span></p></div>
          <div class="section-line"><h2>全部任务 <span>{{tasks.length}}</span></h2><button class="text-button" :disabled="busy" @click="action(refresh)"><IconRefresh :size="16"/>刷新</button></div>
          <section v-if="!tasks.length" class="empty"><IconCalendarTime :size="42" :stroke-width="1.3"/><h3>为第一条消息安排时间</h3><p>{{accounts.length?'选择账号、聊天和每日时间，即可开始。':'先连接一个 Telegram 账号，再创建每日任务。'}}</p><button class="primary" @click="accounts.length?openTask():openLogin()">{{accounts.length?'新建任务':'连接 Telegram 账号'}}<IconArrowRight :size="18"/></button></section>
          <div v-else class="task-list"><article v-for="task in tasks" :key="task.id" class="task-row"><div class="task-time">{{task.time}}<small>{{task.timezone}}</small></div><div class="task-info"><div class="task-title"><h3>{{task.name}}</h3><span class="badge" :class="{paused:!task.enabled}">{{task.enabled?'已启用':'已暂停'}}</span></div><p class="task-target">{{accountName(task.account_id)}} <span>→</span> {{task.chat_title}}</p><p class="message-preview">{{task.text}}</p><small class="muted">{{task.enabled?'下次发送：'+format(task.next_run):'恢复后从下一个未来时间执行'}}</small></div><div class="row-actions"><button :disabled="busy" title="测试发送" aria-label="测试发送" @click="testTask(task)"><IconSend :size="18"/></button><button :disabled="busy" title="编辑" aria-label="编辑任务" @click="openTask(task)"><IconPencil :size="18"/></button><button :disabled="busy" :title="task.enabled?'暂停':'恢复'" :aria-label="task.enabled?'暂停任务':'恢复任务'" @click="toggle(task)"><IconPlayerPause v-if="task.enabled" :size="18"/><IconPlayerPlay v-else :size="18"/></button><button class="danger-icon" :disabled="busy" title="删除" aria-label="删除任务" @click="deleteTask(task)"><IconTrash :size="18"/></button></div></article></div>
        </template>
        <template v-if="tab==='accounts'"><section v-if="!accounts.length" class="empty"><IconUsers :size="42" :stroke-width="1.3"/><h3>连接你的 Telegram</h3><p>在手机 Telegram 的「设置 → 设备」中扫描二维码。</p><button class="primary" :disabled="busy" @click="openLogin">连接账号</button></section><div class="account-list"><article v-for="a in accounts" :key="a.id" class="account-row"><div class="avatar">{{a.label.slice(0,1)}}</div><div class="account-info"><h3>{{a.label}}</h3><p class="muted">{{a.username?'@'+a.username:'ID '+a.id}}</p></div><span class="badge" :class="{paused:a.status!=='connected'}">{{labels[a.status]||a.status}}</span><button :disabled="busy" @click="openLogin">重新授权</button><button class="danger-icon" :disabled="busy" aria-label="退出账号" @click="deleteAccount(a)"><IconLogout :size="18"/></button></article></div><div class="footnote"><h3>连接后会发生什么？</h3><p>扫码授权的是服务器上的 Telegram 客户端。登录会话加密保存，服务重启后会自动恢复。你也可以在手机 Telegram 的设备列表中撤销授权。</p></div></template>
        <template v-if="tab==='runs'"><div class="filters"><label>账号<select v-model="logAccount" @change="logPage=1;action(loadRuns)"><option value="">全部账号</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.label}}</option></select></label><label>任务<select v-model="logTask" @change="logPage=1;action(loadRuns)"><option value="">全部任务</option><option v-for="t in tasks" :key="t.id" :value="t.id">{{t.name}}</option></select></label></div><section v-if="!runs.length" class="empty"><IconHistory :size="42" :stroke-width="1.3"/><h3>还没有执行记录</h3><p>任务执行或测试发送后，结果会出现在这里。</p></section><div v-else class="table-wrap"><table><thead><tr><th>任务 / 目标聊天</th><th>计划时间 / 实际开始</th><th>结果</th><th>说明</th></tr></thead><tbody><tr v-for="r in runs" :key="r.id"><td><strong>{{r.task_name}}</strong><small>{{r.chat_title}} · {{r.kind==='manual'?'手动测试':'每日任务'}}</small><small>{{accountName(r.account_id)}}</small></td><td>{{format(r.scheduled_at)}}<small>{{format(r.started_at)}}</small></td><td><span class="badge" :class="{paused:r.status!=='success'}">{{labels[r.status]||r.status}}</span></td><td class="run-error">{{r.error||(r.message_id?'消息 ID '+r.message_id:'—')}}</td></tr></tbody></table></div><div class="pagination"><span class="muted">共 {{logTotal}} 条 · 第 {{logPage}} 页</span><button :disabled="busy||logPage===1" @click="logPage--;action(loadRuns)">上一页</button><button :disabled="busy||logPage*50>=logTotal" @click="logPage++;action(loadRuns)">下一页</button></div></template>
        <footer>Telegram Daily <span>按时发送，从容安排。</span></footer>
      </div>
    </main>
    <div v-if="modal" class="modal-backdrop" @click.self="closeModal" @keydown.esc="closeModal"><section class="modal" role="dialog" aria-modal="true" :aria-label="modal==='task'?'编辑任务':'连接账号'"><header><div><span class="eyebrow">{{modal==='task'?'DAILY MESSAGE':'TELEGRAM LOGIN'}}</span><h2>{{modal==='task'?(editId?'编辑任务':'新建每日任务'):'连接 Telegram 账号'}}</h2></div><button aria-label="关闭弹窗" @click="closeModal"><IconX :size="20"/></button></header><p v-if="error" role="alert" class="error">{{error}}</p>
      <form v-if="modal==='task'" @submit.prevent="saveTask"><label>任务名称<input v-model="form.name" required maxlength="100" placeholder="例如：每日签到"></label><div class="form-grid"><label>发送账号<select v-model="form.account_id" required @change="changeAccount"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.label}}</option></select></label><label>每日发送时间<input v-model="form.time" type="time" required></label></div><label>目标聊天<div class="search-field"><IconSearch :size="17"/><input v-model="chatSearch" placeholder="搜索已加载的聊天、用户名或 ID"></div><select v-model="form.chat_id" required><option disabled value="">{{loadingChats?'正在加载聊天…':'请选择聊天'}}</option><option v-if="editId && !chats.some(c=>c.id===form.chat_id) && form.chat_id" :value="form.chat_id">{{tasks.find(t=>t.id===editId)?.chat_title}}（原目标）</option><option v-for="c in visibleChats" :key="c.id" :value="c.id">{{c.title}} · {{c.kind}}{{c.username?' · @'+c.username:''}}</option></select></label><div class="chat-tools"><small class="muted">已加载 {{chats.length}} 个可发送聊天</small><button type="button" class="text-button" :disabled="loadingChats||busy" @click="action(()=>loadChats(true))">刷新</button><button v-if="hasMore" type="button" class="text-button" :disabled="loadingChats||busy" @click="action(()=>loadChats(false,true))">加载更多</button></div><label>固定文字<textarea v-model="form.text" required maxlength="4096" rows="5" placeholder="输入要发送的文字，支持换行和 /指令"></textarea><small class="muted">{{form.text.length}} / 4096 · 按纯文本发送</small></label><label>任务时区<input v-model="form.timezone" list="timezones" required placeholder="Asia/Shanghai"><datalist id="timezones"><option v-for="zone in zones" :key="zone" :value="zone"/></datalist></label><label class="checkbox"><input v-model="form.enabled" type="checkbox">启用每日自动发送</label><p class="form-note">错过发送时间会跳过本次。保存或恢复后，从下一个未来时间执行。</p><div class="modal-actions"><button type="button" @click="closeModal">取消</button><button class="primary" :disabled="busy||loadingChats">{{busy?'保存中…':'保存任务'}}</button></div></form>
      <div v-else class="qr-panel"><p>手机 Telegram → 设置 → 设备 → 连接桌面设备</p><div v-if="loginStatus==='waiting'" class="qr-box"><img v-if="qr" :src="qr" alt="Telegram 登录二维码" width="280" height="280"><p v-else>正在生成二维码…</p></div><small v-if="loginStatus==='waiting'" class="muted">过期自动刷新 · 当前有效至 {{qrExpiry?new Date(qrExpiry).toLocaleTimeString('zh-CN'):'—'}}</small><form v-if="loginStatus==='password' || loginStatus==='verifying'" @submit.prevent="sendPassword"><label>Telegram 两步验证密码<input v-model="tgPassword" type="password" autocomplete="off" required></label><button class="primary wide" :disabled="busy||loginStatus==='verifying'">{{loginStatus==='verifying'?'正在验证…':'完成验证'}}</button></form><p v-if="loginError" role="alert" class="error">{{loginError}}</p><p class="form-note">登录会话将在服务器加密保存。二维码仅用于授权本服务，请勿分享。</p></div>
    </section></div>
  </div>
</template>
